"use client";

import { type ComponentPropsWithoutRef, forwardRef, useMemo } from "react";
import { EasingCurveDurationField, EasingCurveEaseField, EasingCurveEditor, EasingCurveGraph, EasingCurvePresets, EasingCurveSurface } from "@/components/ui/easing-curve-editor";
import { type MotionSpring, springAt, springOvershoot, springSettleTime } from "./motion-inspector-math";
import { MotionChoiceRow, MotionSlider } from "./motion-inspector-parts";
import { useMotionInspector } from "./motion-inspector-state";
import { cn } from "@/lib/utils";

type PartProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue">;

/** Presets, the curve, the Ease field and Duration. It shows while the value is an easing. */
export const MotionInspectorEasing = forwardRef<HTMLDivElement, Omit<PartProps, "onDurationChange">>(function MotionInspectorEasing({ className, ...props }, ref) {
  const { value, mixed, disabled, readOnly, ranges, container, messages, preview, commit } = useMotionInspector();
  if (value?.type !== "easing") return null;
  return (
    <EasingCurveEditor
      ref={ref}
      label={messages.easing}
      value={value.curve}
      duration={value.duration}
      durationRange={ranges.duration}
      mixed={mixed}
      disabled={disabled}
      readOnly={readOnly}
      container={container}
      messages={{ preset: messages.preset, duration: messages.duration, mixed: messages.mixed }}
      className={cn("w-full", className)}
      onValueChange={(curve) => preview({ curve }, "curve")}
      onValueCommit={(curve) => commit({ curve }, "curve")}
      onDurationChange={(duration) => preview({ duration }, "duration")}
      onDurationCommit={(duration) => commit({ duration }, "duration")}
      {...props}
    >
      <EasingCurveSurface />
      <EasingCurvePresets />
      <EasingCurveEaseField />
      <EasingCurveDurationField />
    </EasingCurveEditor>
  );
});

type GraphProps = PartProps & { spring: MotionSpring };

/** A read-only curve of a spring from start until it settles. */
export function MotionInspectorSpringGraph({ spring, className, ...props }: GraphProps) {
  const { value, shown, mixed, messages } = useMotionInspector();
  const key = JSON.stringify(spring);
  const { easing, range } = useMemo(() => {
    const current = JSON.parse(key) as MotionSpring;
    const settle = springSettleTime(current);
    return { easing: (time: number) => springAt(current, time * settle), range: [-0.25, Math.max(1.75, 1.05 + springOvershoot(current))] as const };
  }, [key]);
  return <EasingCurveGraph label={messages.springCurve} easing={easing} range={range} samples={160} className={cn("w-full", mixed && shown === value && "opacity-40", className)} {...props} />;
}

/** Time or Physics, the spring's curve and its fields. It shows while the value is a spring. */
export const MotionInspectorSpring = forwardRef<HTMLDivElement, PartProps>(function MotionInspectorSpring({ className, ...props }, ref) {
  const { value, shown, ranges, messages, chooseDefinedBy } = useMotionInspector();
  if (value?.type !== "spring" || shown?.type !== "spring") return null;
  return (
    <div ref={ref} data-slot="motion-inspector-spring" className={cn("grid min-w-0 gap-2", className)} {...props}>
      <MotionInspectorSpringGraph spring={shown} />
      <MotionChoiceRow
        data-slot="motion-inspector-defined-by"
        label={messages.definedBy}
        value={value.definedBy}
        options={[
          { value: "time", label: messages.time },
          { value: "physics", label: messages.physics },
        ]}
        onCommit={chooseDefinedBy}
      />
      {value.definedBy === "time" ? (
        <>
          <MotionSlider field="duration" label={messages.duration} value={value.duration} range={ranges.duration} />
          <MotionSlider field="bounce" label={messages.bounce} value={value.bounce} range={ranges.bounce} />
        </>
      ) : (
        <>
          <MotionSlider field="stiffness" label={messages.stiffness} value={value.stiffness} range={ranges.stiffness} />
          <MotionSlider field="damping" label={messages.damping} value={value.damping} range={ranges.damping} />
          <MotionSlider field="mass" label={messages.mass} value={value.mass} range={ranges.mass} />
        </>
      )}
    </div>
  );
});

import type { EasingCurveValue } from "@/components/ui/easing-curve-editor";

export type MotionEasing = { type: "easing"; curve: EasingCurveValue; duration: number; delay?: number };
/** A spring set by how long it feels and how much it bounces. */
export type MotionSpringTime = { type: "spring"; definedBy: "time"; duration: number; bounce: number; delay?: number };
/** A spring set by its physical properties. */
export type MotionSpringPhysics = { type: "spring"; definedBy: "physics"; stiffness: number; damping: number; mass: number; delay?: number };
export type MotionSpring = MotionSpringTime | MotionSpringPhysics;
export type MotionValue = MotionEasing | MotionSpring;

export type MotionRange = { min: number; max: number; step: number; unit?: string };
export type MotionRanges = Record<"duration" | "delay" | "bounce" | "stiffness" | "damping" | "mass", MotionRange>;

export const defaultRanges: MotionRanges = {
  duration: { min: 0.05, max: 3, step: 0.01, unit: "s" },
  delay: { min: 0, max: 2, step: 0.01, unit: "s" },
  bounce: { min: -0.5, max: 0.9, step: 0.01 },
  stiffness: { min: 1, max: 1000, step: 1 },
  damping: { min: 1, max: 100, step: 0.1 },
  mass: { min: 0.1, max: 10, step: 0.1 },
};

const defaultCurve: EasingCurveValue = [0.25, 0.1, 0.25, 1];
const defaultBounce = 0.2;
const settleTolerance = 0.002;
const longestSettle = 10;
const framesPerSecond = 60;

function snap(value: number, { min, max, step }: MotionRange) {
  const decimals = (String(step).split(".")[1] ?? "").length;
  return Math.min(max, Math.max(min, Number((Math.round(value / step) * step).toFixed(decimals))));
}

/** Physical properties for any spring. Duration is the natural period; bounce 0 is critically damped. */
export function springToPhysics(spring: MotionSpring, mass = 1): Omit<MotionSpringPhysics, "delay"> {
  if (spring.definedBy === "physics") return { type: "spring", definedBy: "physics", stiffness: spring.stiffness, damping: spring.damping, mass: spring.mass };
  const frequency = (2 * Math.PI) / spring.duration;
  const ratio = spring.bounce >= 0 ? 1 - spring.bounce : 1 / (1 + spring.bounce);
  return { type: "spring", definedBy: "physics", stiffness: mass * frequency * frequency, damping: 2 * ratio * mass * frequency, mass };
}

/** Duration and bounce for any spring. */
export function springToTime(spring: MotionSpring): Omit<MotionSpringTime, "delay"> {
  if (spring.definedBy === "time") return { type: "spring", definedBy: "time", duration: spring.duration, bounce: spring.bounce };
  const frequency = Math.sqrt(spring.stiffness / spring.mass);
  const ratio = spring.damping / (2 * Math.sqrt(spring.stiffness * spring.mass));
  return { type: "spring", definedBy: "time", duration: (2 * Math.PI) / frequency, bounce: ratio <= 1 ? 1 - ratio : 1 / ratio - 1 };
}

/** The progress of a spring moving from 0 to 1, at a time in seconds. */
export function springAt(spring: MotionSpring, seconds: number) {
  if (seconds <= 0) return 0;
  const { stiffness, damping, mass } = springToPhysics(spring);
  const frequency = Math.sqrt(stiffness / mass);
  const ratio = damping / (2 * Math.sqrt(stiffness * mass));
  if (Math.abs(ratio - 1) < 1e-6) return 1 - Math.exp(-frequency * seconds) * (1 + frequency * seconds);
  if (ratio < 1) {
    const damped = frequency * Math.sqrt(1 - ratio * ratio);
    return 1 - Math.exp(-ratio * frequency * seconds) * (Math.cos(damped * seconds) + ((ratio * frequency) / damped) * Math.sin(damped * seconds));
  }
  const spread = Math.sqrt(ratio * ratio - 1);
  const slow = -frequency * (ratio - spread);
  const fast = -frequency * (ratio + spread);
  return 1 - (fast * Math.exp(slow * seconds) - slow * Math.exp(fast * seconds)) / (fast - slow);
}

/** Seconds until a spring stays at its target, up to ten seconds. */
export function springSettleTime(spring: MotionSpring) {
  let last = 0;
  for (let frame = 1; frame <= longestSettle * framesPerSecond; frame += 1) {
    if (Math.abs(springAt(spring, frame / framesPerSecond) - 1) > settleTolerance) last = frame;
  }
  return Math.max(0.1, (last + 1) / framesPerSecond);
}

/** The furthest a spring travels past its target, as a share of the distance. */
export function springOvershoot(spring: MotionSpring) {
  const { stiffness, damping, mass } = springToPhysics(spring);
  const ratio = damping / (2 * Math.sqrt(stiffness * mass));
  return ratio >= 1 ? 0 : Math.exp((-Math.PI * ratio) / Math.sqrt(1 - ratio * ratio));
}

/** How long a value takes to finish, without its delay. */
export const motionDuration = (value: MotionValue) => (value.type === "easing" ? value.duration : springSettleTime(value));

const withDelay = <T extends MotionValue>(value: T, delay: number | undefined): T => {
  const { delay: _previous, ...rest } = value;
  void _previous;
  return (delay === undefined ? rest : { ...rest, delay }) as T;
};

/** Converts a spring between Time and Physics, keeping its shape as closely as the ranges allow. */
export function convertSpring(spring: MotionSpring, definedBy: MotionSpring["definedBy"], ranges: MotionRanges): MotionSpring {
  if (spring.definedBy === definedBy) return spring;
  if (definedBy === "time") {
    const time = springToTime(spring);
    return withDelay({ ...time, duration: snap(time.duration, ranges.duration), bounce: snap(time.bounce, ranges.bounce) }, spring.delay);
  }
  const physics = springToPhysics(spring);
  return withDelay({ ...physics, stiffness: snap(physics.stiffness, ranges.stiffness), damping: snap(physics.damping, ranges.damping), mass: snap(physics.mass, ranges.mass) }, spring.delay);
}

/** The value for another mode: what it last held, or a start based on the current timing. */
export function switchType(value: MotionValue, type: MotionValue["type"], remembered: { easing?: MotionEasing; spring?: MotionSpring }, ranges: MotionRanges): MotionValue {
  if (value.type === type) return value;
  if (value.type === "easing") {
    return withDelay<MotionSpring>(remembered.spring ?? { type: "spring", definedBy: "time", duration: snap(value.duration, ranges.duration), bounce: defaultBounce }, value.delay);
  }
  return withDelay<MotionEasing>(remembered.easing ?? { type: "easing", curve: defaultCurve, duration: snap(springToTime(value).duration, ranges.duration) }, value.delay);
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldSegments } from "@/components/ui/inspector-field";
import { NumberField, NumberFieldError, NumberFieldLabel, NumberFieldSlider, NumberFieldSliderFill, NumberFieldSliderThumb, NumberFieldValue } from "@/components/ui/number-field";
import type { MotionRange } from "./motion-inspector-math";
import { type MotionInspectorDetail, type MotionPatch, useMotionInspector } from "./motion-inspector-state";
import { cn } from "@/lib/utils";

type DivProps = Omit<ComponentPropsWithoutRef<"div">, "children">;

/** A labelled two-choice switch that fills the panel's width. */
export function MotionSwitch<V extends string>({ label, value, options, onCommit, className, ...props }: DivProps & { label: string; value: V; options: { value: V; label: string }[]; onCommit: (value: V) => void }) {
  const { mixed, disabled, readOnly } = useMotionInspector();
  return (
    <InspectorField label={label} mixed={mixed} disabled={disabled} readOnly={readOnly} className={cn("block min-w-0", className)} {...props}>
      <InspectorFieldLabel className="sr-only" />
      <InspectorFieldSegments className="h-[var(--uicoolkit-field-height,2.5rem)] w-full" value={value} options={options} onCommit={onCommit} />
    </InspectorField>
  );
}

/** A compact choice in a labelled row, styled like Inspector Field's Off/On toggle. */
export function MotionChoiceRow<V extends string>({ label, value, options, onCommit, className, ...props }: DivProps & { label: string; value: V; options: { value: V; label: string }[]; onCommit: (value: V) => void }) {
  const { mixed, disabled, readOnly } = useMotionInspector();
  return (
    <InspectorField
      label={label}
      labelPosition="inside"
      mixed={mixed}
      disabled={disabled}
      readOnly={readOnly}
      // The same filled box as the sliders around it.
      className={cn("min-w-0 [--uicoolkit-field-bg:var(--muted)] [--uicoolkit-field-border:transparent] [--uicoolkit-field-shadow:none]", className)}
      {...props}
    >
      <InspectorFieldLabel />
      <div className="flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 items-center justify-end gap-2 pr-1 pl-2">
        <InspectorFieldSegments className="w-36" highlightClassName="bg-foreground/10 shadow-none ring-0" value={value} options={options} onCommit={onCommit} />
      </div>
    </InspectorField>
  );
}

type SliderProps = DivProps & { field: Exclude<MotionInspectorDetail["field"], "type" | "definedBy" | "curve">; label: string; value: number; range: MotionRange };

/** A number slider for one property of the current value. */
export function MotionSlider({ field, label, value, range, className, ...props }: SliderProps) {
  const { mixed, disabled, readOnly, messages, preview, commit } = useMotionInspector();
  const patch = (next: number): MotionPatch => ({ [field]: next });
  return (
    <NumberField
      data-slot={`motion-inspector-${field}`}
      className={cn("min-w-0", className)}
      label={label}
      value={mixed ? null : value}
      placeholder={messages.mixed}
      min={range.min}
      max={range.max}
      step={range.step}
      unit={range.unit}
      disabled={disabled}
      readOnly={readOnly}
      onValueChange={(next) => preview(patch(next), field)}
      onValueCommit={(next) => commit(patch(next), field)}
      {...props}
    >
      <NumberFieldSlider className="h-[var(--uicoolkit-field-height,2.5rem)]">
        <NumberFieldSliderFill />
        <NumberFieldSliderThumb />
        <NumberFieldLabel />
        <NumberFieldValue />
      </NumberFieldSlider>
      <NumberFieldError />
    </NumberField>
  );
}

/** Asks your app to play the transition. It shows when you pass onReplay and something is selected. */
export const MotionInspectorReplay = forwardRef<HTMLButtonElement, Omit<ComponentPropsWithoutRef<"button">, "children">>(function MotionInspectorReplay({ className, onClick, ...props }, ref) {
  const { value, disabled, container, messages, onReplay } = useMotionInspector();
  if (!value || !onReplay) return null;
  return (
    <Tooltip.Provider delay={400}>
      <Tooltip.Root>
        <Tooltip.Trigger
          render={
            <button
              ref={ref}
              type="button"
              aria-label={messages.replay}
              disabled={disabled}
              data-slot="motion-inspector-replay"
              className={cn(
                "inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors select-none hover:bg-foreground/10 hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none pointer-coarse:size-11 [&_svg]:size-4",
                className,
              )}
              onClick={(event) => {
                onClick?.(event);
                if (!event.defaultPrevented) onReplay();
              }}
              {...props}
            >
              <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
                <path d="M3 8a5 5 0 1 0 1.5-3.6L3 5.8M3 2.8v3h3" />
              </svg>
            </button>
          }
        />
        <Tooltip.Portal container={container ?? undefined}>
          <Tooltip.Positioner side="top" sideOffset={6} className="z-50">
            <Tooltip.Popup className="rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md pointer-coarse:hidden">{messages.replay}</Tooltip.Popup>
          </Tooltip.Positioner>
        </Tooltip.Portal>
      </Tooltip.Root>
    </Tooltip.Provider>
  );
});

/** The panel's name and Replay. Pass children to replace the name. */
export const MotionInspectorHeader = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function MotionInspectorHeader({ className, children, ...props }, ref) {
  const { label } = useMotionInspector();
  return (
    <div ref={ref} data-slot="motion-inspector-header" className={cn("flex min-h-8 items-center justify-between gap-2", className)} {...props}>
      <span aria-hidden className="min-w-0 truncate font-medium text-foreground">
        {children ?? label}
      </span>
      <MotionInspectorReplay />
    </div>
  );
});

/** Switches between Easing and Spring. */
export function MotionInspectorMode(props: DivProps) {
  const { value, messages, chooseType } = useMotionInspector();
  if (!value) return null;
  return (
    <MotionSwitch
      data-slot="motion-inspector-mode"
      label={messages.type}
      value={value.type}
      options={[
        { value: "easing", label: messages.easing },
        { value: "spring", label: messages.spring },
      ]}
      onCommit={chooseType}
      {...props}
    />
  );
}

/** How long to wait before starting. It shows when the value includes a delay. */
export function MotionInspectorDelay(props: DivProps) {
  const { value, ranges, messages } = useMotionInspector();
  if (value?.delay === undefined) return null;
  return <MotionSlider field="delay" label={messages.delay} value={value.delay} range={ranges.delay} {...props} />;
}

type EmptyProps = ComponentPropsWithoutRef<"div"> & { icon?: ReactNode };

/** Shown when nothing is selected: an icon with the text centred below it, like every empty state in the kit. */
export const MotionInspectorEmpty = forwardRef<HTMLDivElement, EmptyProps>(function MotionInspectorEmpty({ icon, className, children, ...props }, ref) {
  const { value, messages } = useMotionInspector();
  if (value) return null;
  return (
    <div ref={ref} data-slot="motion-inspector-empty" className={cn("flex flex-col items-center justify-center gap-2.5 px-4 py-10 text-center text-sm text-muted-foreground", className)} {...props}>
      <span aria-hidden className="grid size-10 place-items-center rounded-full bg-muted [&_svg]:size-5">
        {icon ?? (
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
            <path d="M3 16C9 16 8 4 17 4" />
          </svg>
        )}
      </span>
      <p className="max-w-52 text-balance">{children ?? messages.empty}</p>
    </div>
  );
});

"use client";

import { forwardRef, useEffect, useRef, useState } from "react";
import { type MotionEasing, type MotionSpring, type MotionValue, convertSpring, defaultRanges, switchType } from "./motion-inspector-math";
import { MotionInspectorDelay, MotionInspectorEmpty, MotionInspectorHeader, MotionInspectorMode } from "./motion-inspector-parts";
import { MotionInspectorEasing, MotionInspectorSpring } from "./motion-inspector-editors";
import { type MotionInspectorDetail, type MotionInspectorProps, type MotionPatch, MotionInspectorContext, defaultMessages } from "./motion-inspector-state";
import { cn } from "@/lib/utils";

const sameValue = (a: MotionValue, b: MotionValue) => JSON.stringify(a) === JSON.stringify(b);

/** Edits how a selected item animates, as an easing curve or a spring. It runs no animation itself. */
export const MotionInspector = forwardRef<HTMLDivElement, MotionInspectorProps>(function MotionInspector(
  { value, onValueCommit, onValueChange, onReplay, label, mixed = false, ranges: rangeOverrides, container, disabled = false, readOnly = false, messages: messageOverrides, className, children, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const ranges = { ...defaultRanges, ...rangeOverrides };
  // A live value belongs to the committed value it started from, so a new selection drops it.
  const [live, setLive] = useState<{ base: MotionValue; next: MotionValue } | null>(null);
  const remembered = useRef<{ easing?: MotionEasing; spring?: MotionSpring }>({});

  useEffect(() => {
    if (value?.type === "easing") remembered.current.easing = value;
    if (value?.type === "spring") remembered.current.spring = value;
  }, [value]);

  const merge = (current: MotionValue, patch: MotionPatch) => ({ ...current, ...patch }) as MotionValue;
  const preview = (patch: MotionPatch, field: MotionInspectorDetail["field"]) => {
    if (!value) return;
    const next = merge(value, patch);
    setLive(sameValue(next, value) ? null : { base: value, next });
    onValueChange?.(next, { field });
  };
  const commit = (patch: MotionPatch, field: MotionInspectorDetail["field"]) => {
    if (!value) return;
    setLive(null);
    onValueCommit(merge(value, patch), { field });
  };
  const replace = (next: MotionValue, field: MotionInspectorDetail["field"]) => {
    setLive(null);
    onValueChange?.(next, { field });
    onValueCommit(next, { field });
  };
  const chooseType = (type: MotionValue["type"]) => {
    if (value && (mixed || value.type !== type)) replace(switchType(value, type, remembered.current, ranges), "type");
  };
  const chooseDefinedBy = (definedBy: MotionSpring["definedBy"]) => {
    if (value?.type === "spring" && (mixed || value.definedBy !== definedBy)) replace(convertSpring(value, definedBy, ranges), "definedBy");
  };

  return (
    <MotionInspectorContext.Provider
      value={{
        value,
        shown: value && live?.base === value ? live.next : value,
        label,
        mixed,
        disabled,
        readOnly,
        ranges,
        container,
        messages,
        onReplay,
        preview,
        commit,
        chooseType,
        chooseDefinedBy,
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="motion-inspector" data-mixed={mixed ? "" : undefined} data-disabled={disabled ? "" : undefined} className={cn("grid w-full min-w-0 content-start gap-2 text-sm", className)} {...props}>
        {children ?? (
          <>
            <MotionInspectorHeader />
            <MotionInspectorEmpty />
            <MotionInspectorMode />
            <MotionInspectorEasing />
            <MotionInspectorSpring />
            <MotionInspectorDelay />
          </>
        )}
      </div>
    </MotionInspectorContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, createContext, useContext } from "react";
import type { MotionEasing, MotionRanges, MotionSpring, MotionSpringPhysics, MotionSpringTime, MotionValue } from "./motion-inspector-math";

/** Replaceable text, for example to translate. */
export type MotionInspectorMessages = {
  type: string;
  easing: string;
  spring: string;
  definedBy: string;
  preset: string;
  time: string;
  physics: string;
  duration: string;
  bounce: string;
  stiffness: string;
  damping: string;
  mass: string;
  delay: string;
  mixed: string;
  replay: string;
  springCurve: string;
  empty: string;
};

export const defaultMessages: MotionInspectorMessages = {
  type: "Animation",
  easing: "Easing",
  spring: "Spring",
  definedBy: "Type",
  preset: "Type",
  time: "Time",
  physics: "Physics",
  duration: "Duration",
  bounce: "Bounce",
  stiffness: "Stiffness",
  damping: "Damping",
  mass: "Mass",
  delay: "Delay",
  mixed: "Mixed",
  replay: "Replay",
  springCurve: "Spring curve",
  empty: "Select an item to edit its motion.",
};

/** What changed. */
export type MotionInspectorDetail = { field: "type" | "definedBy" | "curve" | "duration" | "delay" | "bounce" | "stiffness" | "damping" | "mass" };

/** Fields that can change together on the current value. */
export type MotionPatch = Partial<Omit<MotionEasing, "type"> & Omit<MotionSpringTime, "type" | "definedBy"> & Omit<MotionSpringPhysics, "type" | "definedBy">>;

export type MotionInspectorProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> & {
  /** The committed transition, or null when nothing is selected. Your app owns it. Include `delay` to show the Delay field. */
  value: MotionValue | null;
  /** Called once per finished edit, for saving and undo. */
  onValueCommit: (value: MotionValue, detail: MotionInspectorDetail) => void;
  /** Called with live values while dragging, and with the committed value when a drag is cancelled. */
  onValueChange?: (value: MotionValue, detail: MotionInspectorDetail) => void;
  /** Called by Replay. Your app plays the transition. Passing it shows the button. */
  onReplay?: () => void;
  /** The panel's visible and accessible name, such as "Transition". */
  label: string;
  /** Selected items differ. Fields show Mixed, `value` is where editing starts, and the first edit commits a complete value. */
  mixed?: boolean;
  /** Limits, steps and units for the number fields. */
  ranges?: Partial<MotionRanges>;
  /** Where the preset menu and tooltip are portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  disabled?: boolean;
  readOnly?: boolean;
  messages?: Partial<MotionInspectorMessages>;
};

export type MotionInspectorContextValue = {
  /** The committed value. */
  value: MotionValue | null;
  /** The live value while editing, otherwise the committed value. */
  shown: MotionValue | null;
  label: string;
  mixed: boolean;
  disabled: boolean;
  readOnly: boolean;
  ranges: MotionRanges;
  container?: HTMLElement | null;
  messages: MotionInspectorMessages;
  onReplay?: () => void;
  preview: (patch: MotionPatch, field: MotionInspectorDetail["field"]) => void;
  commit: (patch: MotionPatch, field: MotionInspectorDetail["field"]) => void;
  chooseType: (type: MotionValue["type"]) => void;
